-- Delete any existing pending_list context for this user
DELETE FROM public.panelist_context 
WHERE telegram_id = '{{ $("When Executed by Another Workflow").first().json.telegram_id }}'
  AND context_type = 'pending_list';
-- Insert new pending_list context with the parcels array
INSERT INTO public.panelist_context (telegram_id, context_type, context_data)
VALUES (
    '{{ $("When Executed by Another Workflow").first().json.telegram_id }}',
    'pending_list',
    '{{ JSON.stringify($("Aggregate").first().json.response) }}'::jsonb
);
SELECT '{{ $("When Executed by Another Workflow").first().json.telegram_id }}' AS telegram_id,
       '{{ JSON.stringify($("Aggregate").first().json.response) }}' AS parcels_list;

